/**
 * 2027_06_10_uxw01_orphan_links_to_tech_gov.php
 * ═══════════════════════════════════════════════════════════════════════════
 * الروابطُ اليتيمةُ (ورقةُ «الروابط اليتيمة» — 174 رابطًا) تُنقل فورًا إلى
 * مركزِ الحوكمةِ التقنيِّ حتى قرارِ المالكِ صفًّا صفًّا (UXW-01 §8 + أمرُ المالك):
 *   ① جدولُ `gov_orphan_links` يحفظ الورقةَ الحاكمةَ حرفًا — الرابطُ وتصنيفُه
 *     الحيُّ ومجموعتُه المقترحةُ وطريقةُ الاقتراح · وقرارُ المالكِ فارغٌ حتى يصدر.
 *   ② روابطُها الحيةُ في مجموعاتِ «أخرى — للمراجعة» (مرحلة 99) تُعطَّل
 *     (active=0) — تعطيلٌ قابلٌ للعكسِ لا حذف، والصفُّ باقٍ شاهدًا —
 *     فلا يراها موظفُ تشغيلٍ ولا جهةٌ خارجية.
 *   ③ ما في المقبرةِ 99 وليس في الورقةِ لا يُمَسُّ — يُعَدُّ ويُعلَن رقمًا.
 * ═══════════════════════════════════════════════════════════════════════════
 */
if (php_sapi_name() !== 'cli') { exit("CLI فقط\n"); }
error_reporting(E_ALL & ~E_DEPRECATED);
mb_internal_encoding('UTF-8');

$ROOT = dirname(dirname(__DIR__));
require_once $ROOT . '/includes/env.php';
$host = ems_env('DB_HOST'); $port = 3306;
if (strpos($host, ':') !== false) { list($host, $port) = explode(':', $host); $port = (int) $port; }
mysqli_report(MYSQLI_REPORT_OFF);
$u = ems_env('DB_MIGRATOR_USER') ?: ems_env('DB_USER');
$p = ems_env('DB_MIGRATOR_USER') ? ems_env('DB_MIGRATOR_PASS') : ems_env('DB_PASS');
$conn = new mysqli($host, $u, $p, ems_env('DB_NAME'), $port);
if ($conn->connect_errno) { exit("تعذّر الاتصال: {$conn->connect_error}\n"); }
$conn->set_charset('utf8mb4');
$one = function (string $s) use ($conn) { $r = $conn->query($s); return $r ? ($r->fetch_row()[0] ?? null) : null; };

echo "\n▐ ① جدولُ الورقةِ الحاكمة\n";
if ($conn->query(
    "CREATE TABLE IF NOT EXISTS `gov_orphan_links` (
        `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
        `company_id` INT UNSIGNED NOT NULL DEFAULT 0,
        `sheet_role` VARCHAR(120) NOT NULL COMMENT 'الورقةُ الحية — دورُ القائمةِ في الدفتر',
        `label_ar` VARCHAR(200) NOT NULL,
        `route` VARCHAR(160) NOT NULL,
        `live_class` VARCHAR(120) NOT NULL DEFAULT '' COMMENT 'التصنيفُ الحي',
        `proposed_group` VARCHAR(160) NOT NULL DEFAULT '' COMMENT 'المجموعةُ المقترحةُ في الدفتر',
        `proposal_method` VARCHAR(120) NOT NULL DEFAULT '',
        `owner_decision` ENUM('pending','approved','relocated','retired') NOT NULL DEFAULT 'pending'
            COMMENT 'قرارُ المالكِ صفًّا صفًّا — pending حتى يصدر',
        `decided_at` DATETIME NULL,
        `deactivated_nav_ids` VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'روابطُ nav_items التي عُطِّلت — للعكسِ الدقيق',
        `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (`id`),
        UNIQUE KEY `uq_orphan` (`sheet_role`,`route`,`label_ar`),
        KEY `ix_decision` (`owner_decision`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        COMMENT='UXW-01 §8 — الروابطُ اليتيمةُ في مركزِ الحوكمةِ التقنيِّ حتى قرارِ المالك'") === false) {
    exit("   ✗ إنشاءُ الجدول: {$conn->error}\n");
}

