$ins = $conn->prepare(
    "INSERT INTO `gov_orphan_links`
        (`company_id`,`sheet_role`,`label_ar`,`route`,`live_class`,`proposed_group`,`proposal_method`)
     VALUES (0,?,?,?,?,?,?)
     ON DUPLICATE KEY UPDATE `live_class`=VALUES(`live_class`),
        `proposed_group`=VALUES(`proposed_group`), `proposal_method`=VALUES(`proposal_method`)"
);
$n = 0;
foreach ($SHEET as $r) {
    $ins->bind_param('ssssss', $r[0], $r[1], $r[2], $r[3], $r[4], $r[5]);
    if ($ins->execute()) { $n++; } else { echo "   ✗ {$r[2]}: {$ins->error}\n"; }
}
$ins->close();
printf("   ✔ بُذرت الورقةُ: %d من 174 · في الجدول: %s\n", $n, $one("SELECT COUNT(*) FROM `gov_orphan_links`"));

echo "\n▐ ② تعطيلُ روابطِها الحيةِ في مقبرةِ المرحلةِ 99\n";
printf("   · روابطُ 99 النشطةُ قبل: %s\n", $one(
    "SELECT COUNT(*) FROM nav_items n JOIN link_groups g ON g.id=n.group_id
      WHERE n.active=1 AND g.stage_no=99"));

$deact = 0;
$sel = $conn->prepare(
    "SELECT GROUP_CONCAT(n.id) ids FROM nav_items n
       JOIN link_groups g ON g.id=n.group_id
      WHERE n.active=1 AND g.stage_no=99 AND n.route=?");
$upd = $conn->prepare("UPDATE gov_orphan_links SET deactivated_nav_ids=? WHERE sheet_role=? AND route=? AND label_ar=?");
foreach ($SHEET as $r) {
    $sel->bind_param('s', $r[2]);
    $sel->execute();
    $ids = $sel->get_result()->fetch_assoc()['ids'];
    if ($ids === null) continue;
    $conn->query("UPDATE nav_items SET active=0 WHERE id IN ({$ids})");
    $deact += $conn->affected_rows;
    $upd->bind_param('ssss', $ids, $r[0], $r[2], $r[1]);
    $upd->execute();
}
$sel->close(); $upd->close();
$left = $one("SELECT COUNT(*) FROM nav_items n JOIN link_groups g ON g.id=n.group_id WHERE n.active=1 AND g.stage_no=99");
printf("   ✔ عُطِّل %d رابطًا — والباقي نشطًا في 99 (ليس في الورقة — يُعلَن لا يُمَسّ): %s\n", $deact, $left);

echo "\n✔ اليتيمةُ محفوظةٌ في `gov_orphan_links` بقرارٍ معلَّقٍ — وخارجَ أعينِ التشغيل\n";